package com.smartmart.order.controller; import com.smartmart.order.dto.*; import com.smartmart.order.service.OrderService; import com.smartmart.user.entity.User; import jakarta.validation.Valid; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/cart") @RequiredArgsConstructor @PreAuthorize("hasRole('SHOPPER')") public class CartController{private final OrderService s;@GetMapping public CartResponse cart(@AuthenticationPrincipal User u){return s.cart(u);}@PostMapping public CartResponse add(@AuthenticationPrincipal User u,@Valid @RequestBody CartRequest r){return s.add(u,r);}@PutMapping("/{productId}") public CartResponse update(@AuthenticationPrincipal User u,@PathVariable Long productId,@RequestParam int quantity){return s.update(u,productId,quantity);}@DeleteMapping("/{productId}") public void remove(@AuthenticationPrincipal User u,@PathVariable Long productId){s.remove(u,productId);}@PostMapping("/checkout") public OrderResponse checkout(@AuthenticationPrincipal User u){return s.checkout(u);}}
